const t = $json;
const destination = t.destination || 'your destination';
const dates = `${t.start_date} to ${t.end_date}`;
const packing = t.reminder_type === '2_day' ? '\n\nPacking reminder: start packing and check your travel essentials.' : '';
const message = `Your trip to ${destination} is coming up (${dates}).${packing}`;
const base = {...t, message, email_subject: `Travel reminder: ${destination}`, sent_at: new Date().toISOString()};
const channels = [];
if (t.notify_email && t.email) channels.push('email');
if (t.notify_telegram && t.telegram_chat_id) channels.push('telegram');
return channels.map(channel => ({json: {...base, channel}}));
